import WXFGrid
try:
    from typing import List, Optional
except:
    pass

class WXFT(object):

    # WXFT
    def __init__(
        self,
        FIELD_ID = None,
        MODEL_CLASS = 0,
        MODEL_ID = None,
        MODEL_VERSION = None,
        INIT_TIME_MS = 0,
        LEAD_HOURS = 0.0,
        VALID_TIME_MS = 0,
        HORIZON_HOURS = 0,
        MEMBER_KIND = 0,
        MEMBER_INDEX = 0,
        ENSEMBLE_SIZE = 0,
        PERCENTILE = 0.0,
        THRESHOLD_VALUE = 0.0,
        VARIABLE = 0,
        VARIABLE_NAME = None,
        UNITS = None,
        LEVEL_KIND = 0,
        LEVEL_VALUE = 0.0,
        TEMPORAL_KIND = 0,
        ACCUMULATION_HOURS = 0.0,
        GRID = None,
        TILE_INDEX = 0,
        TILE_COUNT = 1,
        VALUES_ENCODING = 0,
        VALUES = None,
        CHUNK_CID = None,
        CHUNK_DTYPE = None,
        CHUNK_CODECS = None,
        CHUNK_BYTE_LENGTH = 0,
        VALUE_MIN = 0.0,
        VALUE_MAX = 0.0,
        MISSING_COUNT = 0,
        ORIGIN_ID = None,
        DATASET_ID = None,
        SOURCE_URL = None,
        RETRIEVED_AT = 0,
        LICENSE_CLASS = 0,
        LICENSE_URL = None,
        CITATION = None,
        PRODUCER_PEER_ID = None,
    ):
        self.FIELD_ID = FIELD_ID  # type: Optional[str]
        self.MODEL_CLASS = MODEL_CLASS  # type: int
        self.MODEL_ID = MODEL_ID  # type: Optional[str]
        self.MODEL_VERSION = MODEL_VERSION  # type: Optional[str]
        self.INIT_TIME_MS = INIT_TIME_MS  # type: int
        self.LEAD_HOURS = LEAD_HOURS  # type: float
        self.VALID_TIME_MS = VALID_TIME_MS  # type: int
        self.HORIZON_HOURS = HORIZON_HOURS  # type: int
        self.MEMBER_KIND = MEMBER_KIND  # type: int
        self.MEMBER_INDEX = MEMBER_INDEX  # type: int
        self.ENSEMBLE_SIZE = ENSEMBLE_SIZE  # type: int
        self.PERCENTILE = PERCENTILE  # type: float
        self.THRESHOLD_VALUE = THRESHOLD_VALUE  # type: float
        self.VARIABLE = VARIABLE  # type: int
        self.VARIABLE_NAME = VARIABLE_NAME  # type: Optional[str]
        self.UNITS = UNITS  # type: Optional[str]
        self.LEVEL_KIND = LEVEL_KIND  # type: int
        self.LEVEL_VALUE = LEVEL_VALUE  # type: float
        self.TEMPORAL_KIND = TEMPORAL_KIND  # type: int
        self.ACCUMULATION_HOURS = ACCUMULATION_HOURS  # type: float
        self.GRID = GRID  # type: Optional[WXFGrid.WXFGridT]
        self.TILE_INDEX = TILE_INDEX  # type: int
        self.TILE_COUNT = TILE_COUNT  # type: int
        self.VALUES_ENCODING = VALUES_ENCODING  # type: int
        self.VALUES = VALUES  # type: Optional[List[float]]
        self.CHUNK_CID = CHUNK_CID  # type: Optional[str]
        self.CHUNK_DTYPE = CHUNK_DTYPE  # type: Optional[str]
        self.CHUNK_CODECS = CHUNK_CODECS  # type: Optional[List[Optional[str]]]
        self.CHUNK_BYTE_LENGTH = CHUNK_BYTE_LENGTH  # type: int
        self.VALUE_MIN = VALUE_MIN  # type: float
        self.VALUE_MAX = VALUE_MAX  # type: float
        self.MISSING_COUNT = MISSING_COUNT  # type: int
        self.ORIGIN_ID = ORIGIN_ID  # type: Optional[str]
        self.DATASET_ID = DATASET_ID  # type: Optional[str]
        self.SOURCE_URL = SOURCE_URL  # type: Optional[str]
        self.RETRIEVED_AT = RETRIEVED_AT  # type: int
        self.LICENSE_CLASS = LICENSE_CLASS  # type: int
        self.LICENSE_URL = LICENSE_URL  # type: Optional[str]
        self.CITATION = CITATION  # type: Optional[str]
        self.PRODUCER_PEER_ID = PRODUCER_PEER_ID  # type: Optional[str]

    @classmethod
    def InitFromBuf(cls, buf, pos):
        tmpWxf = WXF()
        tmpWxf.Init(buf, pos)
        return cls.InitFromObj(tmpWxf)

    @classmethod
    def InitFromPackedBuf(cls, buf, pos=0):
        n = flatbuffers.encode.Get(flatbuffers.packer.uoffset, buf, pos)
        return cls.InitFromBuf(buf, pos+n)

    @classmethod
    def InitFromObj(cls, tmpWxf):
        x = WXFT()
        x._UnPack(tmpWxf)
        return x

    # WXFT
    def _UnPack(self, WXF):
        if WXF is None:
            return
        self.FIELD_ID = WXF.FIELD_ID()
        self.MODEL_CLASS = WXF.MODEL_CLASS()
        self.MODEL_ID = WXF.MODEL_ID()
        self.MODEL_VERSION = WXF.MODEL_VERSION()
        self.INIT_TIME_MS = WXF.INIT_TIME_MS()
        self.LEAD_HOURS = WXF.LEAD_HOURS()
        self.VALID_TIME_MS = WXF.VALID_TIME_MS()
        self.HORIZON_HOURS = WXF.HORIZON_HOURS()
        self.MEMBER_KIND = WXF.MEMBER_KIND()
        self.MEMBER_INDEX = WXF.MEMBER_INDEX()
        self.ENSEMBLE_SIZE = WXF.ENSEMBLE_SIZE()
        self.PERCENTILE = WXF.PERCENTILE()
        self.THRESHOLD_VALUE = WXF.THRESHOLD_VALUE()
        self.VARIABLE = WXF.VARIABLE()
        self.VARIABLE_NAME = WXF.VARIABLE_NAME()
        self.UNITS = WXF.UNITS()
        self.LEVEL_KIND = WXF.LEVEL_KIND()
        self.LEVEL_VALUE = WXF.LEVEL_VALUE()
        self.TEMPORAL_KIND = WXF.TEMPORAL_KIND()
        self.ACCUMULATION_HOURS = WXF.ACCUMULATION_HOURS()
        if WXF.GRID() is not None:
            self.GRID = WXFGrid.WXFGridT.InitFromObj(WXF.GRID())
        self.TILE_INDEX = WXF.TILE_INDEX()
        self.TILE_COUNT = WXF.TILE_COUNT()
        self.VALUES_ENCODING = WXF.VALUES_ENCODING()
        if not WXF.VALUESIsNone():
            if np is None:
                self.VALUES = []
                for i in range(WXF.VALUESLength()):
                    self.VALUES.append(WXF.VALUES(i))
            else:
                self.VALUES = WXF.VALUESAsNumpy()
        self.CHUNK_CID = WXF.CHUNK_CID()
        self.CHUNK_DTYPE = WXF.CHUNK_DTYPE()
        if not WXF.CHUNK_CODECSIsNone():
            self.CHUNK_CODECS = []
            for i in range(WXF.CHUNK_CODECSLength()):
                self.CHUNK_CODECS.append(WXF.CHUNK_CODECS(i))
        self.CHUNK_BYTE_LENGTH = WXF.CHUNK_BYTE_LENGTH()
        self.VALUE_MIN = WXF.VALUE_MIN()
        self.VALUE_MAX = WXF.VALUE_MAX()
        self.MISSING_COUNT = WXF.MISSING_COUNT()
        self.ORIGIN_ID = WXF.ORIGIN_ID()
        self.DATASET_ID = WXF.DATASET_ID()
        self.SOURCE_URL = WXF.SOURCE_URL()
        self.RETRIEVED_AT = WXF.RETRIEVED_AT()
        self.LICENSE_CLASS = WXF.LICENSE_CLASS()
        self.LICENSE_URL = WXF.LICENSE_URL()
        self.CITATION = WXF.CITATION()
        self.PRODUCER_PEER_ID = WXF.PRODUCER_PEER_ID()

    # WXFT
    def Pack(self, builder):
        if self.FIELD_ID is not None:
            FIELD_ID = builder.CreateString(self.FIELD_ID)
        if self.MODEL_ID is not None:
            MODEL_ID = builder.CreateString(self.MODEL_ID)
        if self.MODEL_VERSION is not None:
            MODEL_VERSION = builder.CreateString(self.MODEL_VERSION)
        if self.VARIABLE_NAME is not None:
            VARIABLE_NAME = builder.CreateString(self.VARIABLE_NAME)
        if self.UNITS is not None:
            UNITS = builder.CreateString(self.UNITS)
        if self.GRID is not None:
            GRID = self.GRID.Pack(builder)
        if self.VALUES is not None:
            if np is not None and type(self.VALUES) is np.ndarray:
                VALUES = builder.CreateNumpyVector(self.VALUES)
            else:
                WXFStartVALUESVector(builder, len(self.VALUES))
                for i in reversed(range(len(self.VALUES))):
                    builder.PrependFloat32(self.VALUES[i])
                VALUES = builder.EndVector()
        if self.CHUNK_CID is not None:
            CHUNK_CID = builder.CreateString(self.CHUNK_CID)
        if self.CHUNK_DTYPE is not None:
            CHUNK_DTYPE = builder.CreateString(self.CHUNK_DTYPE)
        if self.CHUNK_CODECS is not None:
            CHUNK_CODECSlist = []
            for i in range(len(self.CHUNK_CODECS)):
                CHUNK_CODECSlist.append(builder.CreateString(self.CHUNK_CODECS[i]))
            WXFStartCHUNK_CODECSVector(builder, len(self.CHUNK_CODECS))
            for i in reversed(range(len(self.CHUNK_CODECS))):
                builder.PrependUOffsetTRelative(CHUNK_CODECSlist[i])
            CHUNK_CODECS = builder.EndVector()
        if self.ORIGIN_ID is not None:
            ORIGIN_ID = builder.CreateString(self.ORIGIN_ID)
        if self.DATASET_ID is not None:
            DATASET_ID = builder.CreateString(self.DATASET_ID)
        if self.SOURCE_URL is not None:
            SOURCE_URL = builder.CreateString(self.SOURCE_URL)
        if self.LICENSE_URL is not None:
            LICENSE_URL = builder.CreateString(self.LICENSE_URL)
        if self.CITATION is not None:
            CITATION = builder.CreateString(self.CITATION)
        if self.PRODUCER_PEER_ID is not None:
            PRODUCER_PEER_ID = builder.CreateString(self.PRODUCER_PEER_ID)
        WXFStart(builder)
        if self.FIELD_ID is not None:
            WXFAddFIELD_ID(builder, FIELD_ID)
        WXFAddMODEL_CLASS(builder, self.MODEL_CLASS)
        if self.MODEL_ID is not None:
            WXFAddMODEL_ID(builder, MODEL_ID)
        if self.MODEL_VERSION is not None:
            WXFAddMODEL_VERSION(builder, MODEL_VERSION)
        WXFAddINIT_TIME_MS(builder, self.INIT_TIME_MS)
        WXFAddLEAD_HOURS(builder, self.LEAD_HOURS)
        WXFAddVALID_TIME_MS(builder, self.VALID_TIME_MS)
        WXFAddHORIZON_HOURS(builder, self.HORIZON_HOURS)
        WXFAddMEMBER_KIND(builder, self.MEMBER_KIND)
        WXFAddMEMBER_INDEX(builder, self.MEMBER_INDEX)
        WXFAddENSEMBLE_SIZE(builder, self.ENSEMBLE_SIZE)
        WXFAddPERCENTILE(builder, self.PERCENTILE)
        WXFAddTHRESHOLD_VALUE(builder, self.THRESHOLD_VALUE)
        WXFAddVARIABLE(builder, self.VARIABLE)
        if self.VARIABLE_NAME is not None:
            WXFAddVARIABLE_NAME(builder, VARIABLE_NAME)
        if self.UNITS is not None:
            WXFAddUNITS(builder, UNITS)
        WXFAddLEVEL_KIND(builder, self.LEVEL_KIND)
        WXFAddLEVEL_VALUE(builder, self.LEVEL_VALUE)
        WXFAddTEMPORAL_KIND(builder, self.TEMPORAL_KIND)
        WXFAddACCUMULATION_HOURS(builder, self.ACCUMULATION_HOURS)
        if self.GRID is not None:
            WXFAddGRID(builder, GRID)
        WXFAddTILE_INDEX(builder, self.TILE_INDEX)
        WXFAddTILE_COUNT(builder, self.TILE_COUNT)
        WXFAddVALUES_ENCODING(builder, self.VALUES_ENCODING)
        if self.VALUES is not None:
            WXFAddVALUES(builder, VALUES)
        if self.CHUNK_CID is not None:
            WXFAddCHUNK_CID(builder, CHUNK_CID)
        if self.CHUNK_DTYPE is not None:
            WXFAddCHUNK_DTYPE(builder, CHUNK_DTYPE)
        if self.CHUNK_CODECS is not None:
            WXFAddCHUNK_CODECS(builder, CHUNK_CODECS)
        WXFAddCHUNK_BYTE_LENGTH(builder, self.CHUNK_BYTE_LENGTH)
        WXFAddVALUE_MIN(builder, self.VALUE_MIN)
        WXFAddVALUE_MAX(builder, self.VALUE_MAX)
        WXFAddMISSING_COUNT(builder, self.MISSING_COUNT)
        if self.ORIGIN_ID is not None:
            WXFAddORIGIN_ID(builder, ORIGIN_ID)
        if self.DATASET_ID is not None:
            WXFAddDATASET_ID(builder, DATASET_ID)
        if self.SOURCE_URL is not None:
            WXFAddSOURCE_URL(builder, SOURCE_URL)
        WXFAddRETRIEVED_AT(builder, self.RETRIEVED_AT)
        WXFAddLICENSE_CLASS(builder, self.LICENSE_CLASS)
        if self.LICENSE_URL is not None:
            WXFAddLICENSE_URL(builder, LICENSE_URL)
        if self.CITATION is not None:
            WXFAddCITATION(builder, CITATION)
        if self.PRODUCER_PEER_ID is not None:
            WXFAddPRODUCER_PEER_ID(builder, PRODUCER_PEER_ID)
        WXF = WXFEnd(builder)
        return WXF
